cd /run/stage/world && node -e '
const fs=require("fs");
const night=JSON.parse(fs.readFileSync("night.json","utf8"));
const plan=JSON.parse(fs.readFileSync("shift-plan.json","utf8"));
const late=JSON.parse(fs.readFileSync("operations/duty-2340.json","utf8"));
const eta=night.efficiency, h=night.slotHours;
const load=late.limits.map(k=>night.siteLimitKw-k);
const rows=[];
for(let s=0;s<plan.acKw.length;s++){
  const bus=night.buses.find(b=>s>=b.fromSlot&&s<b.untilSlot);
  const inWindow=!!bus;
  const capOk=plan.acKw[s]<=late.limits[s]+1e-9;
  const siteOk=load[s]+plan.acKw[s]<=night.siteLimitKw+1e-9;
  const chargerOk=plan.acKw[s]<=night.chargerKw+1e-9;
  rows.push({slot:plan.slotStart[s],bus:bus?.id??null,setKw:plan.acKw[s],limitKw:late.limits[s],impliedLoadKw:load[s],inWindow,capOk,siteOk,chargerOk});
}
const departures=night.buses.map(b=>{
  let ac=0; for(let s=b.fromSlot;s<b.untilSlot;s++) ac+=plan.acKw[s]*h;
  const end=b.startKwh+ac*eta;
  return {id:b.id,acKwh:ac,endKwh:+end.toFixed(6),requiredKwh:b.requiredKwh,capacityKwh:b.capacityKwh,marginKwh:+(end-b.requiredKwh).toFixed(6),capacityOk:end<=b.capacityKwh+1e-9,meets:end+1e-9>=b.requiredKwh};
});
const low=night.buses.map(b=>{
  let ac=0; for(let s=b.fromSlot;s<b.untilSlot;s++) ac+=late.limits[s]*h;
  return {id:b.id,maxAcKwh:ac,maxBatteryKwh:ac*night.lowerEfficiency,requiredGainKwh:b.requiredKwh-b.startKwh,shortKwh:+((b.requiredKwh-b.startKwh)-ac*night.lowerEfficiency).toFixed(6)};
});
console.log(JSON.stringify({rows,departures,at85:low,allSlotChecks:rows.every(r=>r.inWindow&&r.capOk&&r.siteOk&&r.chargerOk),allDeparturesOk:departures.every(d=>d.capacityOk&&d.meets)},null,2));
'
